UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Balm of Gilead</strong> is a desert shrub resin used for <strong>wound healing</strong>.$$
WHERE common_name = 'Balm Of Gilead';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Bayberry</strong> (wax myrtle) is an <strong>astringent</strong> herb rooted in both traditional Black American herbal practices - where bayberry bark was listed as a <strong>stabilizer</strong> - and in the herbal knowledge exchanged between Cherokee nations and African Americans in North America. In Thompson's Standard Protocol, <strong>Bayberry</strong> (myrica) serves as a more gentle removal of waste via <strong>berberine</strong>. Clinically it is indicated for <strong>upper GI excess</strong> as an astringent and for <strong>lower GI excess</strong>.$$
WHERE common_name = 'Bayberry';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Bearberry</strong> (Uva ursi, Arctostaphylos uva-ursi family) is a <strong>urinary antiseptic</strong>, <strong>antimicrobial</strong>, and <strong>anti-inflammatory</strong> herb that kills bacteria in the <strong>urinary tract</strong> and is specifically indicated for <strong>UTIs</strong>, used together with <a href="?herb=112"><strong>Usnea</strong></a>. In tincture it addresses <strong>fibroids</strong> and <strong>vaginitis</strong>. Topically, <strong>Bearberry</strong> is <strong>astringent</strong> for <strong>wound wash</strong> preparations.$$
WHERE common_name = 'Bearberry';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Bee Balm</strong> is an <strong>antimicrobial</strong> herb used in <strong>wound wash</strong> preparations, where thymol and carvacrol provide potent <strong>broad-spectrum antiseptic</strong> activity.$$
WHERE common_name = 'Bee Balm';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Bergamot</strong> essential oil and hydrosol carry a <strong>photosensitivity</strong> hazard warning.$$
WHERE common_name = 'Bergamot';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Bidens</strong> is an <strong>antimicrobial</strong> herb used in <strong>wound wash</strong> preparations; its antimicrobial activity comes from polyacetylenes and the fresh plant is preferred.$$
WHERE common_name = 'Bidens';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Bilberry</strong> (blueberry/huckleberry leaf) is a <strong>hypoglycemic</strong> that works by inhibiting <strong>liver gluconeogenesis</strong> (release of glucose from glycogen); it does not increase <strong>insulin sensitivity</strong>. <strong>Avoid or use cautiously for type 1 diabetes.</strong> Bilberry leaf could potentially cause <strong>liver damage</strong> (anthraquinones); use cautiously or avoid in <strong>insulin resistance</strong>.$$
WHERE common_name = 'Bilberry';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Bitter Melon</strong> (Momordica charantia) is a <strong>digestive tonic</strong>, <strong>cooling</strong>, and <strong>anti-inflammatory</strong> herb with actions including <strong>anthelmintic</strong>, <strong>abortifacient</strong>, <strong>antiviral</strong>, <strong>emmenagogue</strong>, <strong>hypoglycemic</strong>, and <strong>hypocholesterolemic</strong>; it lowers <strong>blood sugar</strong> and <strong>cholesterol</strong> and is a <strong>glucose-regulating</strong> herb useful for <strong>thyroid health</strong>. It can be used for both non-insulin-dependent and <strong>insulin-dependent diabetes</strong>, is good for <strong>insulin resistance (IR)</strong> combined with elevated <strong>blood lipids</strong>, and can prevent and treat <strong>diabetic neuropathy</strong>. For <strong>type 2 diabetes</strong> combine with <a href="?herb=2232"><strong>Gymnema</strong></a>, <a href="?herb=91"><strong>Fenugreek</strong></a>, <a href="?herb=1547"><strong>Kudzu Root</strong></a>, and CoQ10; for <strong>IR</strong> combine with <a href="?herb=15"><strong>American Ginseng</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=13"><strong>Holy Basil</strong></a>, and <a href="?herb=158"><strong>Barberry</strong></a>. Used in the "Temple of Devotion" <strong>PCOS</strong> formula for <strong>blood sugar regulation</strong>; also used as food, tincture, or for <strong>diabetic neuropathy</strong>. Dose: powder 2 #00 capsules 2-3x/day, tincture 1:2 2-4 ml TID, standardized extract 100-200 mg TID, juice 10-20 ml BID. <strong>Contraindication: monitor blood sugar levels closely.</strong>$$
WHERE common_name = 'Bitter Melon';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Black Cohosh</strong> is an <strong>anti-inflammatory</strong>, <strong>alterative</strong>, <strong>anodyne</strong>, and <strong>nervine</strong> herb - THE classic remedy for <strong>rheumatoid arthritis</strong>, <strong>fibromyalgia</strong>, and <strong>extreme muscle tension</strong> - specific for dull, aching, muscular pain, acute inflammatory <strong>rheumatic pains</strong>, <strong>back tension</strong>, <strong>tension headaches</strong>, <strong>anxiety</strong>, and <strong>PMS with tight squeezing cramps and muscle pain</strong>. As a <strong>serotonin agonist</strong> it works via pituitary influence on serotonin production, supports <strong>estrogen balance</strong> and <strong>melatonin production</strong>, alters the body's perception of pain, and is associated with intrusive negative thoughts and chronic pain with negative self-talk - consider before resorting to SSRIs. Specifically indicated for "black cloud" <strong>hormonal depression</strong> with a menopausal root; acts as a <strong>hormone balancer</strong> for <strong>perimenopause</strong>, <strong>premenopause</strong>, and post-menopausal bodies; and influences <strong>bone mineral loss</strong> (<strong>osteoporosis</strong>, <strong>osteopenia</strong>). As a <strong>uterine tonic</strong> and <strong>astringent</strong> (alongside <a href="?herb=72"><strong>Blue Cohosh</strong></a> and <a href="?herb=157"><strong>Periwinkle</strong></a>), it is indicated for <strong>severe dysmenorrhea</strong>, <strong>PMS with insomnia</strong>, <strong>fibroids</strong> and <strong>vaginitis</strong> - consider as an alternative to <a href="?herb=1009"><strong>Dong Quai</strong></a> for fibroids - and supports female and male <strong>reproductive deficiency</strong> as a circulatory stimulant (use little in males); also used for <strong>blood pressure regulation during pregnancy</strong>. Root listed as a <strong>hormonal stabilizer</strong> in traditional Black American herbal practices and in Shereel's cancer report; included in the <strong>anti-inflammatory</strong> protocol for <strong>PMOS</strong>, in anti-cancer formula 2, and as a <strong>nervine</strong> and <strong>anti-inflammatory</strong> in <strong>cancer</strong> support. Black cohosh leaves were historically used for <strong>chills</strong> and as a <strong>vermifuge</strong> (antiparasitic), prepared as an infusion or taken raw; western herbalists typically use the root, while the leaf is more gentle for <strong>urinary</strong> support. In formulas: acute muscle tension - <a href="?herb=2624"><strong>Pedicularis</strong></a> + <strong>Black Cohosh</strong> + <a href="?herb=124"><strong>Ginger</strong></a>; <strong>musculoskeletal excess</strong> - <strong>Black Cohosh</strong> + <a href="?herb=132"><strong>Lobelia</strong></a> + <a href="?herb=137"><strong>Passionflower</strong></a> + <a href="?herb=142"><strong>Skullcap</strong></a> (disperse blood from musculature into viscera); PMOS pain - <a href="?herb=81"><strong>St. John's Wort</strong></a> + <a href="?herb=75"><strong>Meadowsweet</strong></a> + <strong>Black Cohosh</strong>. Indicated for <strong>base of skull headaches</strong>, but <strong>can actually cause headaches if dose is too high</strong>; use lower dose for <strong>autoimmune disease</strong> with ECM and <strong>fibromyalgia</strong>. Dose: tincture maximum 25 drops per dose (10-25 drops); capsules #00 1-2 to 3x/day.$$
WHERE common_name = 'Black Cohosh';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Black Haw</strong> (Viburnum prunifolium) is a <strong>smooth muscle relaxant</strong> for <strong>painful menstrual cycles</strong>, used interchangeably with <a href="?herb=93"><strong>Cramp Bark</strong></a> but preferred over Cramp Bark when <strong>hypertension</strong> is also present - the first choice for <strong>hypertension in pregnancy</strong>, especially for miscarriage-prone patients, with long folk use for <strong>gestational hypertension</strong>. Indicated for female <strong>reproductive excess</strong> (to cool the system) and male <strong>reproductive excess</strong>.$$
WHERE common_name = 'Black Haw';
